import React from 'react';

import styles from '../../css/Footer.module.css'

const Footer = () => {
  return (
    <footer className={styles.footer}>
      <div className='container'>
        <div className="footer__inner"></div>
      </div>
    </footer>
  );
}

export default Footer;
